content.content:
bin/price:3:echo $(( ($1 * 90 + 99) / 100 ))
bin/quote:3:echo "quote: $(( ($1 * 90 + 99) / 100 ))"
lib/invoice.sh:3:echo "member total $(( ($1 * 90 + 99) / 100 ))"
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( ($1 * 90 + 99) / 100 ))"
#!/bin/bash
# Invoice line for a member order.
echo "member total $(( ($1 * 90 + 99) / 100 ))"
#!/bin/bash
fail=0
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
price 999
quote 999
invoice 999
exit=1

